import json
from pathlib import Path
out=Path('Docs/ArtReviews/Round54');base='Artifacts/Round54/Captures/'
def item(id,score,title,names,obs,revision):return dict(id=id,score=score,max=5,title=title,evidence=[base+n+'.png' for n in names],observation=obs,revision=revision,reviewer='/root/popup54_world actual54 static observation')
items=[item('A1',5,'大头短肢与俯视轮廓清晰',['character-adventurer','character-elementalist','character-swordsman','10-biome-0','10-biome-1','10-biome-2'],'三角色均大头短肢；棕发、紫尖帽和深蓝发在近景与正常俯视中有明确外轮廓，鞋与头躯层级清楚。','保留头身比例与帽发轮廓。'),item('A2',4,'面部、服饰、装备有设计与辨识度',['character-adventurer','character-elementalist','character-swordsman'],'脸有瞳孔高光、眉嘴和颊红，围巾/背带/扣带/金边区分三角色；手肘与衣褶仍简化，眼部纵长造型较突出，局部结构精细度扣1分。','增加少量关节与衣褶变化，保留远镜头简洁。'),item('A3',5,'明快卡通造型材质色彩光照协调',['terrain-detail-'+str(i) for i in [0,1,2,3,5,6]],'青绿、沙金、冰蓝、灰紫橙、灰绿菌紫和赤晶玫瑰有不同主辅色；柔和阴影与描边/分面统一，雪地仍能分辨白雪蓝冰和角色。','保持主辅色与雪地局部对比。'),item('B1',4,'全部首发角色模型材质挂点完成',['character-adventurer','character-elementalist','character-swordsman','10-biome-0','10-biome-1','10-biome-2'],'三角色模型/材质/服装完整，冒险者灰枪与学徒长杖可辨；正常镜头有独立环绕能力体。手形和持握结构接合较简单，扣1分；未将独立能力体误当断挂点。','精修握柄与手腕衔接，并补三角色转身近景回归。'),item('B2',5,'普通怪与精英凭轮廓动作标识区分',['enemy-'+str(i)+'-'+v for i in [0,1,2,3,5,6,7,8] for v in ['normal','elite']]+['enemy-combat-7-normal','enemy-combat-8-elite'],'八族的圆团/长耳/甲壳/法杖菌帽/高菌帽/蛙肢/晶甲/悬浮晶核轮廓不同，精英皇冠兼角/护甲等额外构件明显。新怪正常战斗仍可识别；动作由独立Combat54补证。','保持精英附加构件和敌方危险色。'),item('B3',5,'四Boss独立造型体量完整表现（扩容六Boss全纳入）',['boss-closeup-'+str(i) for i in [0,1,2,3,5,6]]+['boss-'+str(i) for i in [0,1,2,3,5,6]],'树冠须叶、节状沙虫、白毛冰角、黑岩橙核、菌冠蛙和赤晶护卫各有独立形色，正常镜头明显大于普通敌人；完整攻击/死亡表现由Combat54连续观察贡献，不以近景静态代替。','保持各Boss体量与起手轮廓；动作结论见Combat54。'),item('C1',5,'群系独立地貌与装饰语言（扩容六单群系）',['geography-'+str(i)+'-'+str(j) for i in [0,1,2,3,5,6] for j in range(3)],'林河树丛、沙丘绿洲、冰湖雪脊、熔河玄武岩、菌沼池塘和赤晶岩簇有明确地貌与装饰语言，三位置/近广景完整覆盖。','保持六主题不同地貌主形。'),item('C2',4,'地面植被岩石建筑遗迹层次尺度完整',['geography-wide-5-2','geography-wide-6-2']+['waterside-architecture-wide-'+str(i) for i in [0,1,2,3,5,6]],'前中远大小物、房屋/门架/遗迹、低草小石和较大地貌层次成立；建筑落干地、门口接支路。广镜头仍有大片平底和同构菌石簇，景物组合层次扣1分。赤晶命名waterside图未见水，不据文件名声称临水。','为大平地区分疏密与低地形走势，减少相邻同构簇，保留通行空地。'),item('C3',4,'随机区块接缝遮挡重复与碰撞视觉一致',['world-floating-origin','mixed-boundary-0-6','geography-wide-0-2','geography-wide-5-2','geography-wide-6-2'],'所看正常/广角/远坐标无露底裂缝或明显浮起，树菌遮挡使用透明衰减，玩家中心仍可找；主路连贯。小簇重复和前缘偶有构件堆叠保留1分扣分。静图不证明所有碰撞体或全随机种子。','减少相邻模板重复并回归移动遮挡及区块边缘。'),item('C4',5,'混合地图过渡地标路径交互与探索',['mixed-boundary-'+s for s in ['0-1','0-3','0-6','1-2','1-5','3-5']]+['mixed-lava-shore-close']+['sanctuary-completed-'+str(i) for i in [0,1,2,3,5,6]],'六区域与六边界实际覆盖，色带渐变保留两侧装饰；熔岸末端圆收束、桥路明确。六主题挑战侧路绕阵心、踏石接路，完成图提示消失且场景保留；交互点与路径可辨。','保持挑战阵心空地和过渡两侧的主形。')]
(out/'World54FreshItems.json').write_text(json.dumps(items,ensure_ascii=False,indent=2),encoding='utf-8')
text='# Round54 新鲜独立角色与世界分评\n\n评审人 `/root/popup54_world`；仅用54后台Windows Player原始Camera.Render证据重新评分。原100分20子项/10门槛保持，新增群系、敌人、Boss与武器全部纳入原项。A14/15、B14/15、C18/20，10项最低4，合计46/50。B2/B3动作部分由同候选Combat54独立连续观察汇入最终报告；本分域不据静图单独宣布完整美术通过。\n\n实际查看42张完整画幅辅助表，153张不同静态原图，其中另打开23张原尺寸PNG；动态个人观看0帧。每图SHA256、原尺寸、quality/world侧文件和实际元数据见 [World54FreshObserved.json](World54FreshObserved.json)。辅助表为完整画幅缩小索引，原图未改。Probe原2560×1080工具展示为2048×864，全画幅保留。\n\n|子项|分/5|实际观察及修订方向|\n|---|---:|---|\n'
for it in items:text+=f"|{it['id']} {it['title']}|{it['score']}|{it['observation']} {it['revision']} 证据："+', '.join(Path(p).name for p in it['evidence'][:4])+(' 等。' if len(it['evidence'])>4 else '。')+'|\n'
text+='\n证据完整清单和逐项完整关联见 [World54FreshItems.json](World54FreshItems.json)。未发现世界范围占位、粉色材质、丢贴图、明显破损或露底硬阻断。水岸实际关系按图记录：林地河、荒漠绿洲、雪地冰湖、火山熔河及菌沼池塘在宽景可见，赤晶建筑宽景没有水，不能从文件名断言。\n\n限制：此域153静态不证明持续动态、自然生存难度、精确碰撞、全部随机种子/组合或性能。原报告检查数和源身份仅作归属/行为旁证，不转成美术分。没有桌面或模拟器操作、启动Player/构建或改原图。用户已明确延后性能，不要求7200秒末帧，不宣称性能、音频试听或最终成品通过。52/53原图、分数和计数均未用作54证据。\n'
(out/'World54Fresh.md').write_text(text,encoding='utf-8')
